#!/usr/bin/env bash
# HVM self-contained installer. The application payload is embedded below.
set -Eeuo pipefail

APP_DIR="${HVM_DIR:-/opt/hvm}"
SERVICE="hvm"
PORT="${PORT:-5000}"

if [[ "${EUID}" -ne 0 ]]; then
  echo "Please run as root: sudo bash install.sh"
  exit 1
fi
if ! command -v apt-get >/dev/null 2>&1; then
  echo "This installer supports Ubuntu/Debian (apt) only."
  exit 1
fi

echo "[1/6] Installing system dependencies..."
export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y --no-install-recommends \
  ca-certificates curl git python3 python3-venv python3-pip \
  build-essential pkg-config libffi-dev libssl-dev sqlite3 \
  snapd

echo "[2/6] Extracting embedded HVM application..."
if [[ -e "$APP_DIR" ]]; then
  if [[ -d "$APP_DIR" ]] && [[ -f "$APP_DIR/hvm.py" ]]; then
    BACKUP="${APP_DIR}.backup.$(date +%Y%m%d%H%M%S)"
    echo "Existing HVM directory found; backing it up to $BACKUP"
    cp -a "$APP_DIR" "$BACKUP"
  else
    echo "Refusing to overwrite existing non-HVM path: $APP_DIR"
    exit 1
  fi
fi
install -d -m 0755 "$APP_DIR"
awk 'found {print} /^__HVM_PAYLOAD_BELOW__$/ {found=1}' "$0" \
  | base64 -d | tar -xz -C "$APP_DIR"

if [[ ! -f "$APP_DIR/hvm.py" || ! -f "$APP_DIR/requirements.txt" ]]; then
  echo "Embedded payload is incomplete; aborting."
  exit 1
fi

echo "[3/6] Creating Python environment and installing requirements..."
python3 -m venv "$APP_DIR/.venv"
"$APP_DIR/.venv/bin/python" -m pip install --upgrade pip wheel
"$APP_DIR/.venv/bin/python" -m pip install -r "$APP_DIR/requirements.txt"

echo "[4/6] Creating secure environment configuration..."
if [[ ! -f "$APP_DIR/.env" ]]; then
  SECRET_KEY="$("$APP_DIR/.venv/bin/python" -c 'import secrets; print(secrets.token_urlsafe(48))')"
  ADMIN_PASSWORD="$("$APP_DIR/.venv/bin/python" -c 'import secrets; print(secrets.token_urlsafe(20))')"
  cat > "$APP_DIR/.env" <<EOF
DATABASE_PATH=$APP_DIR/hvm.db
HOST=0.0.0.0
PORT=$PORT
MAIN_ADMIN_USERNAME=admin
MAIN_ADMIN_PASSWORD=$ADMIN_PASSWORD
MAIN_ADMIN_EMAIL=admin@localhost
YOUR_SERVER_IP=127.0.0.1
DEFAULT_STORAGE_POOL=default
SECRET_KEY=$SECRET_KEY
DEBUG_MODE=False
AUTO_BACKUP_INTERVAL=3600
STATS_UPDATE_INTERVAL=5
EOF
  chmod 600 "$APP_DIR/.env"
  echo
  echo "========================================"
  echo " HVM ADMIN LOGIN (SAVE THIS PASSWORD)"
  echo " Username: admin"
  echo " Password: $ADMIN_PASSWORD"
  echo "========================================"
  echo
else
  echo "Existing .env preserved."
fi

echo "[5/6] Configuring LXD (needed for VPS provisioning)..."
if ! command -v lxc >/dev/null 2>&1; then
  snap install lxd
fi
if command -v lxd >/dev/null 2>&1; then
  systemctl enable --now snap.lxd.daemon 2>/dev/null || true
  if [[ ! -d /var/snap/lxd/common/lxd/storage-pools ]]; then
    lxd init --auto || echo "WARNING: LXD auto-initialization failed; configure LXD manually."
  fi
fi

echo "[6/6] Installing and starting the HVM systemd service..."
cat > "/etc/systemd/system/${SERVICE}.service" <<EOF
[Unit]
Description=HVM VPS Management Panel
After=network-online.target snap.lxd.daemon.service
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=$APP_DIR
EnvironmentFile=$APP_DIR/.env
ExecStart=$APP_DIR/.venv/bin/python $APP_DIR/hvm.py
Restart=on-failure
RestartSec=5
UMask=0027

[Install]
WantedBy=multi-user.target
EOF

chmod 600 "$APP_DIR/.env"
systemctl daemon-reload
systemctl enable --now "$SERVICE"

echo
echo "HVM installation finished."
echo "Panel URL: http://SERVER-IP:$PORT"
echo "Service:   systemctl status $SERVICE --no-pager"
echo "Logs:      journalctl -u $SERVICE -f"
echo "App path:  $APP_DIR"

__HVM_PAYLOAD_BELOW__

